export async function post(t,e=null){try{const r=e!==null&&!(e instanceof FormData)&&!(e instanceof URLSearchParams);const o={"X-Requested-With":"XMLHttpRequest"};if(r){o["Content-Type"]="application/json"}const n={method:"POST",headers:o};if(e!==null){n.body=r?JSON.stringify(e):e}const c=await fetch(`${CFG_GLPI.root_doc}/${t}`,n);if(!c.ok){throw new Error("POST request failed")}return c}catch(t){glpi_toast_error(__("An unexpected error occurred."));throw t}}export async function get(t){try{const e={method:"GET",headers:{"X-Requested-With":"XMLHttpRequest"}};const r=await fetch(`${CFG_GLPI.root_doc}/${t}`,e);if(!r.ok){throw new Error("GET request failed")}return r}catch(t){glpi_toast_error(__("An unexpected error occurred."));throw t}}